What will be the output of the following C code?
```
#include <stdio.h>
int main()
{
 printf((43 > 43) ? "value 1 is greater!" : "value 1 is not greater!");
 return 0;
}
```

What will be the output of the following C code?
```
#include <stdio.h>
int main()
{
 int marks = 43;
 if (marks > 90)
 printf("Grade : A ");
 else if (marks > 75)
 printf("Grade : B ");
 else if (marks > 60)
 printf("Grade : C ");
 if (marks > 40)
 printf("Grade : D ");
 else
 printf("Fail ");
 return 0;
}
```

What will be the output of the following C code?
```
#include <stdio.h>
int main(){
 int n = 65;
 if (n >= 75) {
 if (n >= 95) {
 printf("Excellent");
 }
 else
 printf("Pass");
 }
 else
 printf("Fail");
}
```

What will be the output of the following C code?
```
#include <stdio.h>
int main(){
 char grade = 'B';
 switch (grade) {
 case 'A':
 printf("Excellent!\n");
 case 'B':
 case 'C':
 printf("Well done\n");
 case 'D':
 printf("You passed\n");
 case 'F':
 printf("Better try again\n");
 break;
 default:
 printf("Invalid grade\n");
 }
}
```

What will be the output of the following C code?
```
#include <stdio.h>
int main(){
 int a = 11;
 while (a < 20) {
 printf("%d ", a);
 a += 2;
 }
 return 0;
}
```

What will be the output of the following C code?
```
#include <stdio.h>
int main(){
 int i, j;
 for (i = 2; i < 10; i++) {
 for (j = 2; j <= (i / j); j++)
 if (!(i % j))
 break;
 if (j > (i / j))
 printf("%d ", i);
 }
 return 0;
}
```

